### Test 3 — eval-server READY signal on stdout

```typescript
import { spawn } from 'child_process';

it('eval-server: READY signal appears on stdout', (done) => {
  const child = spawn(
    process.execPath,
    ['--import', 'tsx', cliEntry, 'eval-server', '--port', '0', '--idle-timeout', '2'],
    {
      cwd: MINI_REPO,
      stdio: ['ignore', 'pipe', 'pipe'],
      env: {
        ...process.env,
        NODE_OPTIONS: `${process.env.NODE_OPTIONS || ''} --max-old-space-size=8192`.trim(),
      },
    },
  );

  let stdoutBuffer = '';
  child.stdout.on('data', (chunk) => {
    stdoutBuffer += chunk.toString();
    if (stdoutBuffer.includes('GITNEXUS_EVAL_SERVER_READY:')) {
      // Signal arrived on stdout ✅
      child.kill('SIGTERM');
      done();
    }
  });

  child.stderr.on('data', (chunk) => {
    const text = chunk.toString();
    // READY signal must NOT appear on stderr
    if (text.includes('GITNEXUS_EVAL_SERVER_READY:')) {
      child.kill('SIGTERM');
      done(new Error('READY signal appeared on stderr instead of stdout'));
    }
  });

  child.on('close', () => {
    // If child exited without emitting the signal, fail
    if (!stdoutBuffer.includes('GITNEXUS_EVAL_SERVER_READY:')) {
      done(new Error('eval-server exited without emitting READY signal on stdout'));
    }
  });
}, 30000);
```

**Note:** This test depends on the mini-repo being indexed (requires the analyze test to run first, or a pre-indexed `.gitnexus/` fixture). The `--idle-timeout 2` ensures the server self-terminates if the test harness misses the kill.

