 *
 * Cascade under test:
 *   1. Most-common non-generic parent folder  → e.g. "Auth"
 *   2. Grandparent directory (0.5 weight)     → e.g. "Auth" when parent is generic
 *   3. Common name prefix (> 2 members, > 2 chars) → e.g. "Validate"
 *   4. Dominant type + shortest symbol name   → e.g. "Function_dispatch"
 *   5. Fallback                               → "Cluster_N"
 */
import { describe, it, expect } from 'vitest';
import { createKnowledgeGraph } from '../../src/core/graph/graph.js';
import type { GraphNode, GraphRelationship } from '../../src/core/graph/types.js';
import { processCommunities } from '../../src/core/ingestion/community-processor.js';

// ============================================================================
// HELPERS
// ============================================================================

function makeNode(id: string, name: string, label: GraphNode['label'], filePath: string): GraphNode {
  return { id, label, properties: { name, filePath, startLine: 1, endLine: 10, isExported: false } };
}

function makeRel(id: string, src: string, tgt: string): GraphRelationship {
  return { id, sourceId: src, targetId: tgt, type: 'CALLS', confidence: 1.0, reason: '' };
}

/**
 * Build a fully-connected clique and return the heuristic label of the resulting community.
 * All nodes default to 'Function' unless overridden.
 */
async function getLabelForNodes(
  nodes: Array<{ id: string; name: string; filePath: string; label?: GraphNode['label'] }>,
): Promise<string> {
  const graph = createKnowledgeGraph();
  for (const n of nodes) {
    graph.addNode(makeNode(n.id, n.name, n.label ?? 'Function', n.filePath));
  }
  let relIdx = 0;
  for (let i = 0; i < nodes.length; i++) {
    for (let j = i + 1; j < nodes.length; j++) {
      graph.addRelationship(makeRel(`r${relIdx++}`, nodes[i].id, nodes[j].id));
    }
  }
  const result = await processCommunities(graph);
  // A single isolated clique should produce exactly one community
  expect(result.communities).toHaveLength(1);
  return result.communities[0].heuristicLabel;
}

// ============================================================================
// STRATEGY 1: Parent folder label
// ============================================================================

describe('generateHeuristicLabel — cluster labeling', () => {
  describe('Strategy 1: parent folder label', () => {
    it('uses a non-generic parent folder as the label', async () => {
      const label = await getLabelForNodes([
        { id: 'n1', name: 'login',   filePath: 'src/auth/login.ts' },
        { id: 'n2', name: 'logout',  filePath: 'src/auth/logout.ts' },
        { id: 'n3', name: 'refresh', filePath: 'src/auth/refresh.ts' },
      ]);
      expect(label).toBe('Auth');
    });

    it('capitalizes the first letter of the folder name', async () => {
      const label = await getLabelForNodes([
        { id: 'n1', name: 'charge', filePath: 'src/payment/charge.ts' },
        { id: 'n2', name: 'refund', filePath: 'src/payment/refund.ts' },
        { id: 'n3', name: 'verify', filePath: 'src/payment/verify.ts' },
      ]);
      expect(label).toBe('Payment');
    });

    it('picks the most-common folder when members span multiple non-generic folders', async () => {
      // 3 nodes in "auth", 1 node in "billing" → "Auth" wins
      const label = await getLabelForNodes([
        { id: 'n1', name: 'login',   filePath: 'src/auth/login.ts' },
        { id: 'n2', name: 'logout',  filePath: 'src/auth/logout.ts' },
        { id: 'n3', name: 'refresh', filePath: 'src/auth/refresh.ts' },
        { id: 'n4', name: 'charge',  filePath: 'src/billing/charge.ts' },
      ]);
      expect(label).toBe('Auth');
    });

    // ── NEGATIVE ──────────────────────────────────────────────────────────────
    it('does NOT produce a label from generic parent folders (utils, src, lib, …)', async () => {
      const genericFolders = [
        'src', 'lib', 'core', 'utils', 'common', 'shared', 'helpers',
        'components', 'services', 'controllers', 'models',
      ];
      for (const folder of genericFolders) {
        const label = await getLabelForNodes([
          { id: `${folder}_n1`, name: 'fn1', filePath: `${folder}/action1.ts` },
          { id: `${folder}_n2`, name: 'fn2', filePath: `${folder}/action2.ts` },
          { id: `${folder}_n3`, name: 'fn3', filePath: `${folder}/action3.ts` },
        ]);
        const capitalized = folder.charAt(0).toUpperCase() + folder.slice(1);
        expect(label, `folder "${folder}" should be skipped`).not.toBe(capitalized);
      }
    });
  });

  // ============================================================================
  // STRATEGY 2: Grandparent directory fallback
  // ============================================================================

  describe('Strategy 2: grandparent directory fallback', () => {
    it('falls back to grandparent when immediate parent is generic (e.g. middleware)', async () => {
      // src/auth/middleware/validate.ts → parent="middleware" (generic), grandparent="auth"
      const label = await getLabelForNodes([
        { id: 'n1', name: 'validateToken',    filePath: 'src/auth/middleware/validateToken.ts' },
        { id: 'n2', name: 'sanitizeInput',    filePath: 'src/auth/middleware/sanitizeInput.ts' },
        { id: 'n3', name: 'checkPermissions', filePath: 'src/auth/middleware/checkPermissions.ts' },
      ]);
      expect(label).toBe('Auth');
    });

    it('strong parent folder (count=3) beats a shared grandparent (count=1.0)', async () => {
      // payment parent direct × 3  vs  auth grandparent × 2 nodes (each 0.5 = 1.0)
      const label = await getLabelForNodes([
        { id: 'n1', name: 'charge',  filePath: 'src/payment/charge.ts' },
        { id: 'n2', name: 'refund',  filePath: 'src/payment/refund.ts' },
        { id: 'n3', name: 'verify',  filePath: 'src/payment/verify.ts' },
        { id: 'n4', name: 'login',   filePath: 'src/auth/services/login.ts' },  // grandparent=auth +0.5
        { id: 'n5', name: 'logout',  filePath: 'src/auth/services/logout.ts' }, // grandparent=auth +0.5 = total 1.0
      ]);
      // payment(3.0) > auth(1.0) → "Payment"
      expect(label).toBe('Payment');
    });

    // ── NEGATIVE ──────────────────────────────────────────────────────────────
    it('does NOT use grandparent when it is also generic', async () => {
      // src/lib/utils/validate.ts → parent="utils" (generic), grandparent="lib" (generic)
      const label = await getLabelForNodes([
        { id: 'n1', name: 'validateEmail', filePath: 'src/lib/utils/validateEmail.ts' },
        { id: 'n2', name: 'validatePhone', filePath: 'src/lib/utils/validatePhone.ts' },
        { id: 'n3', name: 'validateDate',  filePath: 'src/lib/utils/validateDate.ts' },
      ]);
      expect(label).not.toBe('Utils');
      expect(label).not.toBe('Lib');
    });
  });

  // ============================================================================
  // STRATEGY 3: Common name prefix
  // ============================================================================

  describe('Strategy 3: common name prefix', () => {
    it('extracts common prefix from 3+ symbol names in a generic folder', async () => {
      const label = await getLabelForNodes([
        { id: 'n1', name: 'validateUser',    filePath: 'src/utils/validateUser.ts' },
        { id: 'n2', name: 'validateOrder',   filePath: 'src/utils/validateOrder.ts' },
        { id: 'n3', name: 'validatePayment', filePath: 'src/utils/validatePayment.ts' },
      ]);
      expect(label).toBe('Validate');
    });

    // ── NEGATIVE ──────────────────────────────────────────────────────────────
    it('does NOT use a prefix of 2 characters or fewer', async () => {
      // Common prefix "fn" — only 2 chars, should be skipped
      const label = await getLabelForNodes([
        { id: 'n1', name: 'fnApply',    filePath: 'src/utils/fnApply.ts' },
        { id: 'n2', name: 'fnCompose',  filePath: 'src/utils/fnCompose.ts' },
        { id: 'n3', name: 'fnPipe',     filePath: 'src/utils/fnPipe.ts' },
      ]);
      expect(label).not.toBe('Fn');
    });

    // ── NEGATIVE ──────────────────────────────────────────────────────────────
    it('skips prefix strategy when the cluster has only 2 members (names.length <= 2 check)', async () => {
      // Exactly 2 nodes — the `names.length > 2` guard blocks prefix extraction
      const label = await getLabelForNodes([
        { id: 'n1', name: 'validateUser',  filePath: 'src/utils/validateUser.ts' },
        { id: 'n2', name: 'validateOrder', filePath: 'src/utils/validateOrder.ts' },
      ]);
      // Falls through to dominant type strategy
      expect(label).toMatch(/^Function_/);
    });
  });

  // ============================================================================
  // STRATEGY 4: Dominant type + shortest symbol name
  // ============================================================================

  describe('Strategy 4: dominant type + shortest symbol name', () => {
    it('produces Function_<shortest> when no folder or prefix signal exists', async () => {
      // All generic folders, names have no common prefix
      const label = await getLabelForNodes([
        { id: 'n1', name: 'processRequest', filePath: 'src/utils/processRequest.ts' },
        { id: 'n2', name: 'handleEvent',    filePath: 'lib/helpers/handleEvent.ts' },
        { id: 'n3', name: 'dispatch',       filePath: 'src/core/dispatch.ts' },
      ]);
      // Sorted by length: dispatch(8) < handleEvent(11) < processRequest(14)
      expect(label).toBe('Function_dispatch');
    });

    it('uses the dominant Class type when the majority of nodes are Classes', async () => {
      const label = await getLabelForNodes([
        { id: 'n1', name: 'UserService', label: 'Class',    filePath: 'src/services/UserService.ts' },
        { id: 'n2', name: 'AuthService', label: 'Class',    filePath: 'src/services/AuthService.ts' },
        { id: 'n3', name: 'configure',   label: 'Function', filePath: 'src/services/configure.ts' },
      ]);
      // 2 Class, 1 Function — dominant=Class, shortest name = "configure" (9 chars)
      expect(label).toBe('Class_configure');
    });

    // ── NEGATIVE ──────────────────────────────────────────────────────────────
    it('picks the shortest name, not the alphabetically first name', async () => {
      const label = await getLabelForNodes([
        { id: 'n1', name: 'aaaVeryLongFunctionName', filePath: 'src/utils/a.ts' },
        { id: 'n2', name: 'zzz',                     filePath: 'lib/helpers/b.ts' },
        { id: 'n3', name: 'mmmmmmm',                 filePath: 'src/core/c.ts' },
      ]);
      // "zzz" is shortest (3 chars) even though it sorts last alphabetically
      expect(label).toBe('Function_zzz');
    });
  });

  // ============================================================================
  // CASCADE PRIORITY
  // ============================================================================

  describe('Cascade priority', () => {
    it('folder label takes precedence over a common name prefix', async () => {
      // Both signals present: nodes in "auth/" AND names share "validate" prefix
      const label = await getLabelForNodes([
        { id: 'n1', name: 'validateToken',   filePath: 'src/auth/validateToken.ts' },
        { id: 'n2', name: 'validateSession', filePath: 'src/auth/validateSession.ts' },
        { id: 'n3', name: 'validateCookie',  filePath: 'src/auth/validateCookie.ts' },
      ]);
      expect(label).toBe('Auth');   // not "Validate"
    });

    it('name prefix takes precedence over dominant-type label', async () => {
      const label = await getLabelForNodes([
        { id: 'n1', name: 'parseJSON', filePath: 'src/utils/parseJSON.ts' },
        { id: 'n2', name: 'parseXML',  filePath: 'src/utils/parseXML.ts' },
        { id: 'n3', name: 'parseCSV',  filePath: 'src/utils/parseCSV.ts' },
      ]);
      // "parse" (5 chars > 2) wins over Function_parseCSV
      expect(label).toBe('Parse');
    });
  });

  // ============================================================================
  // EDGE CASES
  // ============================================================================

  describe('Edge cases', () => {
    it('singleton nodes are excluded from community results', async () => {
      const graph = createKnowledgeGraph();
      graph.addNode(makeNode('lone', 'loneFunction', 'Function', 'src/auth/lone.ts'));
      // No edges — will be a singleton and filtered out
      const result = await processCommunities(graph);
      expect(result.communities).toHaveLength(0);
    });

    it('nodes with empty filePath fall back gracefully to type-based label', async () => {
      const label = await getLabelForNodes([
        { id: 'n1', name: 'anonymousFn', filePath: '' },
        { id: 'n2', name: 'anotherFn',   filePath: '' },
        { id: 'n3', name: 'thirdFn',     filePath: '' },
      ]);
      // No path signal, no common prefix → type-based label
      expect(label).toMatch(/^(Function_|Cluster_)/);
    });

    it('two isolated cliques in one graph get distinct, descriptive labels', async () => {
      const graph = createKnowledgeGraph();

      // Clique 1: auth
      for (let i = 0; i < 3; i++) {
        graph.addNode(makeNode(`a${i}`, `authFn${i}`, 'Function', `src/auth/f${i}.ts`));
      }
      graph.addRelationship(makeRel('r1', 'a0', 'a1'));
      graph.addRelationship(makeRel('r2', 'a1', 'a2'));
      graph.addRelationship(makeRel('r3', 'a0', 'a2'));

      // Clique 2: payment (isolated — no cross edges)
      for (let i = 0; i < 3; i++) {
        graph.addNode(makeNode(`p${i}`, `paymentFn${i}`, 'Function', `src/payment/f${i}.ts`));
      }
      graph.addRelationship(makeRel('r4', 'p0', 'p1'));
      graph.addRelationship(makeRel('r5', 'p1', 'p2'));
      graph.addRelationship(makeRel('r6', 'p0', 'p2'));

      const result = await processCommunities(graph);
      expect(result.communities).toHaveLength(2);

      const labels = result.communities.map(c => c.heuristicLabel);
      expect(labels).toContain('Auth');
      expect(labels).toContain('Payment');
    });
  });
});
