### Fix 3 — `hydrateSerializedServerGraph` state resets

`server-graph-hydration.test.ts` verifies the graph is rebuilt and the callback is called, but doesn't verify that `storedFileContents` is **replaced** (not accumulated) and that `isEmbeddingComplete` resets to `false`. These are worker module-level state mutations and need integration-level tests or spy-based checks.

```ts
// Extend server-graph-hydration.test.ts

it('file map is built from fileContents, not accumulated from a previous load', async () => {
  const first: SerializablePipelineResult = {
    nodes: [], relationships: [],
    fileContents: { 'old.ts': 'old content' },
  };
  const second: SerializablePipelineResult = {
    nodes: [], relationships: [],
    fileContents: { 'new.ts': 'new content' },
  };

  const { buildPipelineResultFromSerialized } = await import('./server-graph-hydration');

  const r1 = buildPipelineResultFromSerialized(first);
  const r2 = buildPipelineResultFromSerialized(second);

  // Each call returns an independent Map — no cross-contamination
  expect(r1.fileContents.has('old.ts')).toBe(true);
  expect(r1.fileContents.has('new.ts')).toBe(false);
  expect(r2.fileContents.has('new.ts')).toBe(true);
  expect(r2.fileContents.has('old.ts')).toBe(false);
});

it('handles empty nodes/relationships without throwing', () => {
  const empty: SerializablePipelineResult = {
    nodes: [], relationships: [], fileContents: {},
  };
  const result = buildPipelineResultFromSerialized(empty);
  expect(result.graph.nodeCount).toBe(0);
  expect(result.graph.relationshipCount).toBe(0);
  expect(result.fileContents.size).toBe(0);
});

// NEGATIVE: malformed relationship (non-existent node IDs) must not throw
it('tolerates relationships referencing unknown node IDs', () => {
  const bad: SerializablePipelineResult = {
    nodes: [],
    relationships: [{ source: 'ghost-a', target: 'ghost-b', type: 'CALLS', properties: {} }],
    fileContents: {},
  };
  expect(() => buildPipelineResultFromSerialized(bad)).not.toThrow();
});
